<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { taskApi } from '@/api'
import { useAuthStore } from '@/store/auth'

const auth = useAuthStore()
const isManager = computed(() => ['SUPER_ADMIN', 'DORM_MANAGER'].includes(auth.profile?.userType || ''))
const rows=ref<any[]>([]); const total=ref(0); const loading=ref(false)
const query=reactive({pageNum:1,pageSize:10,status:'',campusId:'',buildingId:''})
const statusVisible=ref(false)
const statusForm=reactive({taskId:'',status:'DOING',imageUrls:'',remark:''})
const generateVisible=ref(false)
const generateForm=reactive({name:'',campusId:'',buildingId:'',items:''})

async function load(){loading.value=true;try{const params:any={...query};Object.keys(params).forEach(k=>{if(params[k]===''||params[k]==null)delete params[k]});const raw:any=await (isManager.value ? taskApi.list(params) : taskApi.my());const body=raw?.data??raw;const records=Array.isArray(body) ? body : (body?.records??[]);rows.value=isManager.value ? records : records.filter((row:any)=>(!query.status||row.status===query.status)&&(!query.campusId||String(row.campusId)===String(query.campusId))&&(!query.buildingId||String(row.buildingId)===String(query.buildingId)));total.value=Number(isManager.value ? (body?.total??rows.value.length) : rows.value.length)}finally{loading.value=false}}
function openStatus(row:any){statusForm.taskId=row.id;statusForm.status=row.status||'DOING';statusForm.imageUrls='';statusForm.remark='';statusVisible.value=true}
async function submitStatus(){try{await taskApi.updateStatus(statusForm);ElMessage.success('状态已更新');statusVisible.value=false;load()}catch{}}
async function submitGenerate(){try{const items=JSON.parse(generateForm.items||'[]');await taskApi.generate({...generateForm,items});ElMessage.success('已生成任务');generateVisible.value=false;load()}catch{ElMessage.warning('items 需为 JSON 数组')}}
onMounted(load)
</script>
<template><section class="hs-page"><div class="hs-page-title"><div class="cn">保洁任务</div><div class="en">Clean Tasks</div><div class="hs-waterline"></div></div><div class="hs-panel"><el-form inline @submit.prevent><el-form-item label="状态"><el-select v-model="query.status" clearable style="width:150px"><el-option v-for="s in ['TODO','DOING','COMPLETED','CANCELLED']" :key="s" :label="s" :value="s"/></el-select></el-form-item><el-form-item label="校区ID"><el-input v-model="query.campusId" clearable style="width:130px"/></el-form-item><el-form-item label="楼栋ID"><el-input v-model="query.buildingId" clearable style="width:130px"/></el-form-item><el-button type="primary" @click="load">查询</el-button><el-button type="primary" v-if="isManager" @click="generateVisible=true">生成任务</el-button></el-form><el-table :data="rows" border stripe v-loading="loading"><el-table-column prop="id" label="ID" width="70"/><el-table-column prop="title" label="任务"/><el-table-column prop="workerName" label="保洁员"/><el-table-column prop="campusName" label="校区"/><el-table-column prop="buildingName" label="楼栋"/><el-table-column prop="status" label="状态"/><el-table-column prop="deadline" label="截止时间"/><el-table-column label="操作" width="100" fixed="right"><template #default="{ row }"><el-button link type="primary" @click="openStatus(row)">更新状态</el-button></template></el-table-column></el-table><div class="pager"><el-pagination v-model:current-page="query.pageNum" v-model:page-size="query.pageSize" :total="total" layout="total, prev, pager, next" @current-change="load"/></div></div><el-dialog v-model="statusVisible" title="更新任务状态" width="480px"><el-form :model="statusForm" label-width="90px"><el-form-item label="任务ID"><el-input v-model="statusForm.taskId"/></el-form-item><el-form-item label="状态"><el-select v-model="statusForm.status"><el-option v-for="s in ['TODO','DOING','COMPLETED','CANCELLED']" :key="s" :label="s" :value="s"/></el-select></el-form-item><el-form-item label="图片URL"><el-input v-model="statusForm.imageUrls"/></el-form-item><el-form-item label="备注"><el-input v-model="statusForm.remark" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="statusVisible=false">取消</el-button><el-button type="primary" @click="submitStatus">保存</el-button></template></el-dialog><el-dialog v-if="isManager" v-model="generateVisible" title="生成任务" width="560px"><el-form :model="generateForm" label-width="90px"><el-form-item label="任务名称"><el-input v-model="generateForm.name"/></el-form-item><el-form-item label="校区ID"><el-input v-model="generateForm.campusId"/></el-form-item><el-form-item label="楼栋ID"><el-input v-model="generateForm.buildingId"/></el-form-item><el-form-item label="任务项JSON"><el-input v-model="generateForm.items" type="textarea" :rows="6" placeholder='[{"workerId":1,"workerName":"张三","areaDesc":"1-3层","taskContent":"清扫走廊","deadline":"2026-08-19T18:00:00"}]'/></el-form-item></el-form><template #footer><el-button @click="generateVisible=false">取消</el-button><el-button type="primary" @click="submitGenerate">生成</el-button></template></el-dialog></section></template>
<style scoped>.pager{display:flex;justify-content:flex-end;margin-top:16px}</style>